const filters=document.querySelectorAll('[data-filter]');function filterCategory(value){const chosen=['all','sla','lithium','graphene'].includes(value)?value:'all';let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=chosen!=='all'&&card.dataset.category!==chosen;if(!card.hidden)count++});filters.forEach(b=>{b.classList.toggle('active',b.dataset.filter===chosen);b.setAttribute('aria-pressed',String(b.dataset.filter===chosen))});const status=document.getElementById('filterCount');if(status)status.textContent=`${count} battery ${count===1?'family':'families'}`;}
filters.forEach(b=>b.addEventListener('click',()=>{filterCategory(b.dataset.filter);const u=new URL(location.href);u.searchParams.set('category',b.dataset.filter);history.replaceState(null,'',u)}));if(filters.length)filterCategory(new URLSearchParams(location.search).get('category')||'all');
const tabs=[...document.querySelectorAll('[data-panel]')];function selectTab(button){tabs.forEach(t=>{const selected=t===button;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById('panel-'+t.dataset.panel).hidden=!selected});}tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectTab(t));t.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectTab(tabs[next]);tabs[next].focus()}})});
const form=document.getElementById('quoteForm');if(form){const params=new URLSearchParams(location.search);const cat=params.get('category');if(['sla','lithium','graphene'].includes(cat))form.elements.category.value=cat;form.elements.model.value=(params.get('model')||'').slice(0,100);form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const category=form.elements.category.selectedOptions[0].textContent;const content=`SUNKA — WHOLESALE ENQUIRY\nMeri Industires\n\nDate: ${new Date().toLocaleDateString()}\nName: ${d.get('name')}\nCompany: ${d.get('company')}\nEmail: ${d.get('email')}\nBattery category: ${category}\nModel: ${d.get('model')||'To be confirmed'}\nQuantity: ${d.get('quantity')} units\n\nRequirements:\n${d.get('requirements')}\n\nPlease confirm model datasheets, pricing, minimum order quantity, availability, lead time and warranty.\n\nPrepared locally. This enquiry has not been sent.\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='SUNKA-wholesale-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('formStatus').textContent='Your enquiry file is ready. Share the downloaded file with your Sunka contact. It has not been sent automatically.'})}
const svg=body=>`<svg viewBox="0 0 320 150" aria-hidden="true">${body}</svg>`,wheels='<circle cx="72" cy="112" r="24"/><circle cx="247" cy="112" r="24"/><circle cx="72" cy="112" r="16" opacity=".4"/><circle cx="247" cy="112" r="16" opacity=".4"/><path d="M25 140h270" stroke="#cbd5be"/>';
const illustrations={scooterArt:svg(wheels+'<path d="M72 112l32-38h76l25 38h42l-29-79h-23m20 0l-8-12h-22M95 72l-9-17h67l14 17M103 77l18 29h53l18-20M226 51h13v15h-9"/>'),rickshawArt:svg('<circle cx="74" cy="115" r="21"/><circle cx="236" cy="115" r="21"/><path d="M28 139h260M52 94V35h126v65H99m-46-65l12-15h118l31 33 18 46h-37V33M68 36v40h46V36m9 0v40h44M52 84h126m13-35h23m-7 16h19m-38 37h25M96 115h119"/>'),fleetArt:svg(wheels+'<path d="M72 112l31-34h80l23 34h41l-28-76h-21M218 36l-6-13h-23M100 76l-4-10h72M104 80l17 26h54l17-19M88 65V22h79v43M128 22v43M88 36h79"/><text x="96" y="53" stroke="none" fill="#3b5944" font-size="15" font-weight="bold">SUNKA</text>')};for(const [id,html]of Object.entries(illustrations)){const el=document.getElementById(id);if(el)el.innerHTML=html;}
